validated":true,"definition":"CHECK (((amount_agorot > 0) AND (currency = ''ILS''::text) AND (provider = ''shutafim''::text)))"},{"name":"event_payment_attempts_event_id_events_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE RESTRICT"},{"name":"event_payment_attempts_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"event_payment_attempts_registration_id_event_participants_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (registration_id) REFERENCES event_participants(id) ON DELETE RESTRICT"},{"name":"event_payment_attempts_registration_id_unique","type":"u","validated":true,"definition":"UNIQUE (registration_id)"},{"name":"event_payment_attempts_status_check","type":"c","validated":true,"definition":"CHECK (((status = ANY (ARRAY[''pending''::text, ''paid''::text, ''cancelled''::text])) AND (selection_hash ~ ''^[0-9a-f]{64}$''::text)))"},{"name":"event_payment_attempts_user_id_users_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT"}]},"telegram_broadcast_deliveries":{"columns":[{"name":"attempts","type":"integer","default":"0","not_null":true},{"name":"broadcast_id","type":"uuid","default":null,"not_null":true},{"name":"claimed_at","type":"timestamp with time zone","default":null,"not_null":false},{"name":"contact_id","type":"uuid","default":null,"not_null":true},{"name":"delivered_at","type":"timestamp with time zone","default":null,"not_null":false},{"name":"error_class","type":"text","default":null,"not_null":false},{"name":"id","type":"uuid","default":"gen_random_uuid()","not_null":true},{"name":"next_attempt_at","type":"timestamp with time zone","default":"now()","not_null":true},{"name":"status","type":"text","default":"''queued''::text","not_null":true}],"indexes":[{"name":"telegram_broadcast_deliveries_pkey","valid":true,"definition":"CREATE UNIQUE INDEX telegram_broadcast_deliveries_pkey ON public.telegram_broadcast_deliveries USING btree (id)"},{"name":"telegram_delivery_due_idx","valid":true,"definition":"CREATE INDEX telegram_delivery_due_idx ON public.telegram_broadcast_deliveries USING btree (status, next_attempt_at, id)"},{"name":"telegram_delivery_recipient_idx","valid":true,"definition":"CREATE UNIQUE INDEX telegram_delivery_recipient_idx ON public.telegram_broadcast_deliveries USING btree (broadcast_id, contact_id)"}],"constraints":[{"name":"telegram_broadcast_deliveries_broadcast_id_telegram_broadcasts_","type":"f","validated":true,"definition":"FOREIGN KEY (broadcast_id) REFERENCES telegram_broadcasts(id) ON DELETE CASCADE"},{"name":"telegram_broadcast_deliveries_contact_id_telegram_contacts_id_f","type":"f","validated":true,"definition":"FOREIGN KEY (contact_id) REFERENCES telegram_contacts(id) ON DELETE RESTRICT"},{"name":"telegram_broadcast_deliveries_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"telegram_delivery_status_check","type":"c","validated":true,"definition":"CHECK (((status = ANY (ARRAY[''queued''::text, ''sending''::text, ''delivered''::text, ''skipped''::text, ''failed''::text, ''unknown''::text])) AND ((attempts >= 0) AND (attempts <= 5))))"}]},"telegram_broadcasts":{"columns":[{"name":"audience","type":"jsonb","default":null,"not_null":true},{"name":"button_label","type":"text","default":null,"not_null":false},{"name":"created_at","type":"timestamp with time zone","default":"now()","not_null":true},{"name":"created_by","type":"text","default":null,"not_null":true},{"name":"event_id","type":"text","default":null,"not_null":false},{"name":"id","type":"uuid","default":"gen_random_uuid()","not_null":true},{"name":"message","type":"text","default":null,"not_null":true},{"name":"recipient_count","type":"integer","default":null,"not_null":true},{"name":"request_key","type":"uuid","default":null,"not_null":true},{"name":"status","type":"text","default":"''queued''::text","not_null":true}],"indexes":[{"name":"telegram_broadcasts_created_idx","valid":true,"definition":"CREATE INDEX telegram_broadcasts_created_idx ON public.telegram_broadcasts USING btree (created_at)"},{"name":"telegram_broadcasts_pkey","valid":true,"definition":"CREATE UNIQUE INDEX telegram_broadcasts_pkey ON public.telegram_broadcasts USING btree (id)"},{"name":"telegram_broadcasts_request_key_unique","valid":true,"definition":"CREATE UNIQUE INDEX telegram_broadcasts_request_key_unique ON public.telegram_broadcasts USING btree (request_key)"}],"constraints":[{"name":"telegram_broadcasts_created_by_users_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT"},{"name":"telegram_broadcasts_event_id_events_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL"},{"name":"telegram_broadcasts_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"telegram_broadcasts_request_key_unique","type":"u","validated":true,"definition":"UNIQUE (request_key)"},{"name":"telegram_broadcasts_status_check","type":"c","validated":true,"definition":"CHECK (((status = ANY (ARRAY[''queued''::text, ''completed''::text, ''cancelled''::text])) AND (recipient_count >= 0) AND ((length(message) >= 1) AND (length(message) <= 3500))))"}]},"telegram_campaigns":{"columns":[{"name":"active","type":"boolean","default":"true","not_null":true},{"name":"event_id","type":"text","default":null,"not_null":false},{"name":"key","type":"text","default":null,"not_null":true}],"indexes":[{"name":"telegram_campaigns_pkey","valid":true,"definition":"CREATE UNIQUE INDEX telegram_campaigns_pkey ON public.telegram_campaigns USING btree (key)"}],"constraints":[{"name":"telegram_campaigns_event_id_events_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL"},{"name":"telegram_campaigns_key_check","type":"c","validated":true,"definition":"CHECK ((key ~ ''^[A-Za-z0-9_-]{1,64}$''::text))"},{"name":"telegram_campaigns_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (key)"}]},"telegram_updates":{"columns":[{"name":"processed_at","type":"timestamp with time zone","default":"now()","not_null":true},{"name":"update_id","type":"text","default":null,"not_null":true}],"indexes":[{"name":"telegram_updates_pkey","valid":true,"definition":"CREATE UNIQUE INDEX telegram_updates_pkey ON public.telegram_updates USING btree (update_id)"}],"constraints":[{"name":"telegram_updates_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (update_id)"}]}}'::jsonb)),
op_status AS (
 SELECT e.table_name,c.oid,c.relrowsecurity,
 c.relkind='r' AND c.relrowsecurity AND NOT row_security_active(c.oid)
 AND NOT EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid)
 AND e.spec=jsonb_build_object(
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attname) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated) ORDER BY k.conname),'[]'::jsonb) FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>'n'),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',i.indexname,'definition',i.indexdef,'valid',x.indisvalid) ORDER BY i.indexname) FROM pg_indexes i JOIN pg_namespace ns ON ns.nspname=i.schemaname JOIN pg_class ic ON ic.relnamespace=ns.oid AND ic.relname=i.indexname JOIN pg_index x ON x.indexrelid=ic.oid WHERE i.schemaname='public' AND i.tablename=e.table_name)) AS compatible
 FROM op_expected e LEFT JOIN pg_namespace n ON n.nspname='public'
 LEFT JOIN pg_class c ON c.relnamespace=n.oid AND c.relname=e.table_name
),
backend AS (SELECT oid FROM op_status UNION ALL SELECT oid FROM core_status WHERE table_name IN('community_audit','community_registration_drafts')),
security_status AS (
 SELECT (SELECT count(*) FROM backend b JOIN pg_class c ON c.oid=b.oid CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) p WHERE p.grantee=0)
 +(SELECT count(*) FROM backend b JOIN pg_attribute a ON a.attrelid=b.oid CROSS JOIN LATERAL aclexplode(a.attacl) p WHERE a.attnum>0 AND NOT a.attisdropped AND p.grantee=0)
 +(SELECT count(*) FROM backend b CROSS JOIN pg_roles r WHERE b.oid IS NOT NULL AND r.rolname IN('anon','authenticated') AND (has_table_privilege(r.oid,b.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=b.oid AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege(r.oid,b.oid,a.attnum,'SELECT,INSERT,UPDATE,REFERENCES')))) AS exposed_grants,
 (SELECT count(*) FROM backend b JOIN pg_policy p ON p.polrelid=b.oid) AS policies
),
query_index_status AS (
 SELECT v.name,c.oid,i.indisvalid AND pg_get_indexdef(c.oid)=v.definition AS compatible
 FROM (VALUES ('events_status_created_idx','CREATE INDEX events_status_created_idx ON public.events USING btree (status, created_at, id)'),('event_participants_owner_event_idx','CREATE INDEX event_participants_owner_event_idx ON public.event_participants USING btree (user_id, event_id, created_at)')) v(name,definition)
 LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||v.name) LEFT JOIN pg_index i ON i.indexrelid=c.oid
) SELECT 'exposed backend privileges/policies' INTO bad FROM security_status WHERE exposed_grants<>0 OR policies<>0;
 IF bad IS NOT NULL THEN RAISE EXCEPTION 'Adoption security mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.users'::regclass AND attname='email' AND attnotnull) THEN RAISE EXCEPTION 'Adoption requires nullable email'; END IF;
 IF EXISTS(SELECT 1 FROM telegram_contacts c LEFT JOIN user_identities i ON i.provider='telegram' AND i.provider_instance='primary' AND i.provider_user_id=c.telegram_user_id WHERE i.id IS NULL OR i.user_id<>c.user_id)
 OR EXISTS(SELECT 1 FROM telegram_contacts GROUP BY user_id HAVING count(*) FILTER(WHERE is_primary)<>1)
 OR EXISTS(SELECT 1 FROM telegram_miniapp_sessions s LEFT JOIN user_identities i ON i.id=s.identity_id WHERE i.id IS NULL OR i.user_id<>s.user_id OR i.provider<>'telegram' OR i.provider_instance<>'primary')
 OR EXISTS(SELECT 1 FROM event_payment_attempts a LEFT JOIN event_participants p ON p.id=a.registration_id WHERE p.id IS NULL OR p.user_id<>a.user_id OR p.event_id<>a.event_id)
 OR EXISTS(SELECT 1 FROM telegram_broadcast_deliveries d LEFT JOIN telegram_contacts c ON c.id=d.contact_id LEFT JOIN telegram_broadcasts b ON b.id=d.broadcast_id WHERE c.id IS NULL OR b.id IS NULL)
 THEN RAISE EXCEPTION 'Adoption identity/registration integrity mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.user_identity_merge_log'::regclass AND tgname='user_identity_merge_log_no_mutation' AND tgenabled IN('O','A')) THEN RAISE EXCEPTION 'Adoption audit guard missing'; END IF;
 END $adoption_schema$;
